#!/usr/bin/env python3
import pathlib, sys
lines = sys.stdin.read().splitlines()
if not lines or lines[0] != '*** Begin Patch' or lines[-1] != '*** End Patch':
    raise SystemExit('expected Begin/End Patch')
i = 1
while i < len(lines) - 1:
    header = lines[i]
    if header.startswith('*** Update File: '):
        path = pathlib.Path(header[len('*** Update File: '):])
        original = path.read_text()
        i += 1
        chunks = []
        current = []
        while i < len(lines) - 1 and not lines[i].startswith('*** '):
            if lines[i].startswith('@@'):
                if current: chunks.append(current); current = []
            else:
                current.append(lines[i])
            i += 1
        if current: chunks.append(current)
        for chunk in chunks:
            old = '\n'.join(line[1:] for line in chunk if line.startswith((' ', '-')))
            new = '\n'.join(line[1:] for line in chunk if line.startswith((' ', '+')))
            if old not in original:
                raise SystemExit(f'old text not found in {path}:\n{old}')
            original = original.replace(old, new, 1)
        path.write_text(original)
    elif header.startswith('*** Add File: '):
        path = pathlib.Path(header[len('*** Add File: '):])
        i += 1
        content = []
        while i < len(lines) - 1 and not lines[i].startswith('*** '):
            content.append(lines[i][1:] if lines[i].startswith('+') else lines[i])
            i += 1
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text('\n'.join(content) + '\n')
    elif header.startswith('*** Delete File: '):
        pathlib.Path(header[len('*** Delete File: '):]).unlink()
        i += 1
    else:
        raise SystemExit(f'unsupported header {header}')
