   175	  private Bson quantified(Call call) {
   176	    Preconditions.checkArgument(call.arguments().size() == 2, "Expected two arguments for %s", call);
   177	    Preconditions.checkArgument(call.arguments().get(0) instanceof Path, "%s is not a path", call.arguments().get(0));
   178	    String field = fieldName(call.arguments().get(0));
   179	    Bson condition = quantifiedCondition(call.arguments().get(1));
   180	    boolean scalarRegex = isScalarRegexPredicate(call.arguments().get(1));
   181	    Bson matches = scalarRegex ? scalarFieldCondition(field, condition) : Filters.elemMatch(field, condition);
   182	    Bson result;
   183	    if (call.operator() == IterableOperators.ANY) {
   184	      result = matches;
   185	    } else if (call.operator() == IterableOperators.NONE) {
   186	      result = Filters.nor(matches);
   187	    } else {
   188	      if (scalarRegex) {
   189	        Bson noNullElements = Filters.nin(field, Collections.singletonList(null));
   190	        Bson noMismatches = noScalarFieldMatch(field, scalarMismatch(call.arguments().get(1)));
   191	        result = Filters.and(noNullElements, noMismatches);
   192	      } else if (isScalarPredicate(call.arguments().get(1))) {
   193	        Bson noNullElements = Filters.nin(field, Collections.singletonList(null));
   194	        Bson noMismatches = Filters.nor(Filters.elemMatch(field, scalarMismatch(call.arguments().get(1))));
   195	        result = Filters.and(noNullElements, noMismatches);
   196	      } else {
   197	        result = Filters.nor(Filters.elemMatch(field, Filters.nor(condition)));
   198	      }
   199	    }
   200	    Bson arrayType = new BsonDocument(field, new BsonDocument("$type", new BsonString("array")));
   201	    return Filters.and(arrayType, result);
   202	  }
