   204	  private static boolean requiresStrictAny(Call call) {
   205	    Preconditions.checkArgument(call.operator() == IterableOperators.ANY, "%s is not ANY", call);
   206	    Expression predicate = call.arguments().get(1);
   207	    if (!(predicate instanceof Call)) {
   208	      return false;
   209	    }
   210	    Operator operator = ((Call) predicate).operator();
   211	    return operator == Operators.NOT_EQUAL
   212	            || operator == Operators.NOT_IN
   213	            || containsNewQuantifier(predicate);
   214	  }
